create extension if not exists pgcrypto;
create table if not exists public.organizations(id uuid primary key default gen_random_uuid(),name text not null,institution_type text not null default 'College',city text,state text,reporting_year integer not null default extract(year from now())::integer,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.organization_members(organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'viewer' check(role in('admin','data_manager','viewer')),created_at timestamptz default now(),primary key(organization_id,user_id));
create table if not exists public.facilities(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,facility_type text not null default 'Academic building',area_sq_m numeric(14,2),is_active boolean not null default true,created_at timestamptz default now());
create table if not exists public.emission_factors(id uuid primary key default gen_random_uuid(),factor_code text not null unique,label text not null,category text not null,scope integer not null check(scope in(1,2,3)),activity_unit text not null,kg_co2e_per_unit numeric(16,8) not null check(kg_co2e_per_unit>=0),geography text not null default 'India',source_name text not null,source_year integer,source_url text,factor_status text not null default 'provisional' check(factor_status in('official','provisional','user_defined')),notes text,active boolean not null default true);
create table if not exists public.activity_records(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,facility_id uuid references public.facilities(id) on delete set null,factor_id uuid not null references public.emission_factors(id),activity_date date not null,period_month date not null,quantity numeric(16,4) not null check(quantity>=0),activity_unit text not null,factor_value_snapshot numeric(16,8) not null,emissions_kg_co2e numeric(18,4) generated always as(quantity*factor_value_snapshot) stored,reference_note text,evidence_file_name text,entered_by uuid not null default auth.uid() references auth.users(id),created_at timestamptz default now());
create index if not exists activity_org_period_idx on public.activity_records(organization_id,period_month);
create or replace function public.create_carbotrack_organization(p_name text,p_type text default 'College',p_city text default null,p_state text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare new_id uuid; begin if auth.uid() is null then raise exception 'Sign in is required'; end if; if length(trim(coalesce(p_name,'')))<2 then raise exception 'Enter an institution name'; end if; insert into public.organizations(name,institution_type,city,state,created_by) values(trim(p_name),coalesce(nullif(trim(p_type),''),'College'),nullif(trim(p_city),''),nullif(trim(p_state),''),auth.uid()) returning id into new_id; insert into public.organization_members(organization_id,user_id,role) values(new_id,auth.uid(),'admin'); return new_id; end; $$;
grant execute on function public.create_carbotrack_organization(text,text,text,text) to authenticated;
create or replace function public.carbotrack_is_member(org_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.organization_members where organization_id=org_id and user_id=auth.uid()); $$;
create or replace function public.carbotrack_can_manage(org_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.organization_members where organization_id=org_id and user_id=auth.uid() and role in('admin','data_manager')); $$;
create or replace function public.carbotrack_is_admin(org_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.organization_members where organization_id=org_id and user_id=auth.uid() and role='admin'); $$;
alter table public.organizations enable row level security; alter table public.organization_members enable row level security; alter table public.facilities enable row level security; alter table public.emission_factors enable row level security; alter table public.activity_records enable row level security;
drop policy if exists org_read_members on public.organizations; create policy org_read_members on public.organizations for select to authenticated using(public.carbotrack_is_member(id));
drop policy if exists org_update_admin on public.organizations; create policy org_update_admin on public.organizations for update to authenticated using(public.carbotrack_is_admin(id)) with check(public.carbotrack_is_admin(id));
drop policy if exists member_read_roster on public.organization_members; create policy member_read_roster on public.organization_members for select to authenticated using(public.carbotrack_is_member(organization_id));
drop policy if exists member_admin_add on public.organization_members; create policy member_admin_add on public.organization_members for insert to authenticated with check(public.carbotrack_is_admin(organization_id) and role in('data_manager','viewer'));
drop policy if exists member_admin_remove on public.organization_members; create policy member_admin_remove on public.organization_members for delete to authenticated using(public.carbotrack_is_admin(organization_id) and user_id<>auth.uid());
drop policy if exists facilities_read_members on public.facilities; create policy facilities_read_members on public.facilities for select to authenticated using(public.carbotrack_is_member(organization_id));
drop policy if exists facilities_manage on public.facilities; create policy facilities_manage on public.facilities for all to authenticated using(public.carbotrack_can_manage(organization_id)) with check(public.carbotrack_can_manage(organization_id));
drop policy if exists factors_read_all on public.emission_factors; create policy factors_read_all on public.emission_factors for select to authenticated using(active=true);
drop policy if exists activity_read_members on public.activity_records; create policy activity_read_members on public.activity_records for select to authenticated using(public.carbotrack_is_member(organization_id));
drop policy if exists activity_insert_managers on public.activity_records; create policy activity_insert_managers on public.activity_records for insert to authenticated with check(public.carbotrack_can_manage(organization_id) and entered_by=auth.uid());
drop policy if exists activity_update_managers on public.activity_records; create policy activity_update_managers on public.activity_records for update to authenticated using(public.carbotrack_can_manage(organization_id)) with check(public.carbotrack_can_manage(organization_id));
drop policy if exists activity_delete_admin on public.activity_records; create policy activity_delete_admin on public.activity_records for delete to authenticated using(public.carbotrack_is_admin(organization_id));
