on conflict(factor_code) do update set label=excluded.label,category=excluded.category,scope=excluded.scope,activity_unit=excluded.activity_unit,kg_co2e_per_unit=excluded.kg_co2e_per_unit,source_name=excluded.source_name,source_year=excluded.source_year,source_url=excluded.source_url,factor_status=excluded.factor_status,notes=excluded.notes;
grant select on public.emission_factors to authenticated;
grant select,insert,update,delete on public.organizations,public.organization_members,public.facilities,public.activity_records to authenticated;